pub fn reference_key_for_aggregate(qualified_name: &str) -> Option<&'static str> {
    match qualified_name {
        "EmbryonautFoundersApp::Member" => Some("member"),
        "EmbryonautFoundersApp::FoundingAgreement" => Some("founding_agreement"),
        "EmbryonautFoundersApp::Client" => Some("client"),
        "EmbryonautFoundersApp::Engagement" => Some("engagement"),
        "EmbryonautFoundersApp::Proposal" => Some("proposal"),
        "EmbryonautFoundersApp::Contract" => Some("contract"),
        "EmbryonautFoundersApp::Product" => Some("product"),
        "EmbryonautFoundersApp::Invoice" => Some("invoice"),
        "EmbryonautFoundersApp::Payment" => Some("payment"),
        "EmbryonautFoundersApp::RecurringPayment" => Some("recurring_payment"),
        "Governance::RoleAssignment" => Some("role_assignment"),
        "Governance::RoleTransition" => Some("role_transition"),
        "Identity::Identity" => Some("identity"),
        "Identity::ExternalIdentifier" => Some("external_identifier"),
        _ => None,
    }
}
